--
-- Struktur dari tabel `koleksi_seni`
--

CREATE TABLE IF NOT EXISTS `koleksi_seni` (
  `id_koleksi` int(11) NOT NULL AUTO_INCREMENT COMMENT 'Kunci Primer Identifikator Unik Artefak',
  `nomor_inventaris` varchar(30) NOT NULL COMMENT 'Kode Registrasi Koleksi Lembaga GLAM',
  `judul_koleksi` varchar(150) NOT NULL COMMENT 'Judul Resmi Karya Seni / Artefak',
  `kategori_koleksi` enum('lukisan','naskah','artefak','wastra') NOT NULL COMMENT 'Klasifikasi Domain Kuratorial',
  `seniman_pencipta` varchar(100) NOT NULL COMMENT 'Nama Maestro / Empu / Tokoh Kreator',
  `tahun_perolehan` int(11) DEFAULT NULL COMMENT 'Tahun Penciptaan atau Estimasi Era Koleksi',
  `asal_daerah` varchar(100) DEFAULT NULL COMMENT 'Wilayah Kultural Asal Koleksi Nusantara',
  `medium_teknik` varchar(100) DEFAULT NULL COMMENT 'Material Fisik dan Teknik Pembuatan',
  `dimensi` varchar(50) DEFAULT NULL COMMENT 'Ukuran Presisi Koleksi Fisik',
  `lokasi_ruang` varchar(50) DEFAULT NULL COMMENT 'Sayap / Ruang Pameran Virtual GLAM',
  `deskripsi` text DEFAULT NULL COMMENT 'Anotasi Sejarah dan Deskripsi Kuratorial',
  `gambar` varchar(255) DEFAULT NULL COMMENT 'Jalur Direktori Berkas Digital Artefak',
  `tanggal_masuk` timestamp NOT NULL DEFAULT current_timestamp() COMMENT 'Waktu Entri Data ke Basis Data Relasional',
  PRIMARY KEY (`id_koleksi`),
  UNIQUE KEY `idx_nomor_inventaris` (`nomor_inventaris`),
  KEY `idx_kategori` (`kategori_koleksi`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

