INSERT INTO `koleksi_seni` (`id_koleksi`, `nomor_inventaris`, `judul_koleksi`, `kategori_koleksi`, `seniman_pencipta`, `tahun_perolehan`, `asal_daerah`, `medium_teknik`, `dimensi`, `lokasi_ruang`, `deskripsi`, `gambar`, `tanggal_masuk`) VALUES
(1, 'NG-1857-001', 'Penangkapan Pangeran Diponegoro', 'lukisan', 'Raden Saleh (c. 1811–1880)', 1857, 'Jawa Tengah', 'Cat minyak pada kanvas', '112 × 179 cm', 'RUANG 01 — LUKISAN SEJARAH', 'Lukisan bersejarah ini merekam peristiwa penangkapan Pangeran Diponegoro oleh Letnan Jenderal Hendrik Merkus de Kock di Magelang pada 28 Maret 1830. Dibuat sebagai respon kultural atas lukisan Nicolaas Pieneman, Raden Saleh menampilkan Diponegoro dengan sikap tegar, menolak tunduk di hadapan otoritas kolonial Belanda.', 'assets/images/koleksi/diponegoro-lukisan.jpg', '2026-11-03 10:00:00'),
(2, 'NG-1846-002', 'Perburuan Rusa (Deer Hunt)', 'lukisan', 'Raden Saleh (c. 1811–1880)', 1846, 'Jawa Tengah', 'Cat minyak pada kanvas', '178 × 262 cm', 'RUANG 01 — LUKISAN SEJARAH', 'Mahakarya beraliran Romantisisme yang melukiskan ketegangan pemburu pribumi berkuda dalam mengejar kawanan rusa di alam liar Nusantara. Sapuan kuas yang dinamis, permainan kontras chiaroscuro, serta anatomi satwa yang akurat menunjukkan kepiawaian teknik Raden Saleh yang diakui istana-istana Eropa.', 'assets/images/koleksi/perburuan-rusa.jpg', '2026-11-03 10:00:00'),
(3, 'NG-1840-003', 'Kapal Karam Diterjang Badai (A Storm at Sea)', 'lukisan', 'Raden Saleh (c. 1811–1880)', 1840, 'Jawa Tengah', 'Cat minyak pada kanvas', '74 × 98 cm', 'RUANG 01 — LUKISAN SEJARAH', 'Sebuah alegori kekuatan alam samudra melawan kerapuhan peradaban manusia. Deburan ombak membuih dan langit kelam pekat mencerminkan filosofi agung (the sublime) yang dipelajari Raden Saleh saat belajar di Dresden dan Den Haag.', 'assets/images/koleksi/badai-raden-saleh.jpg', '2026-11-03 10:00:00'),
(4, 'NG-1848-004', 'Antara Hidup dan Mati (Pertarungan Banteng dan Singa)', 'lukisan', 'Raden Saleh (c. 1811–1880)', 1848, 'Jawa Tengah', 'Cat minyak pada kanvas', '264 × 400 cm', 'RUANG 01 — LUKISAN SEJARAH', 'Lukisan monumental bertema pertarungan satwa eksotis yang melambangkan benturan kekuatan kosmis. Banteng sering ditafsirkan sebagai representasi keteguhan rakyat pribumi menghadapi pemangsa kolonial.', 'assets/images/koleksi/antara-hidup-dan-mati.jpg', '2026-11-03 10:00:00'),
(5, 'NG-1837-005', 'Potret Raden Syarif Bustaman', 'lukisan', 'Raden Saleh (c. 1811–1880)', 1837, 'Semarang, Jawa Tengah', 'Cat minyak pada kanvas', '90 × 75 cm', 'RUANG 01 — LUKISAN SEJARAH', 'Potret paman sekaligus pelindung masa muda sang maestro, Raden Adipati Aryo Suroadimanggolo (Syarif Bustaman), bupati Semarang yang berwawasan luas. Karya ini memadukan ketelitian potret realis Eropa dengan martabat ningrat Nusantara.', 'assets/images/koleksi/potret-syarif-bustan.jpg', '2026-11-03 10:00:00'),
(6, 'NG-1870-006', 'Pasangan Pengantin Bangsawan Jawa', 'lukisan', 'Raden Saleh (c. 1811–1880)', 1870, 'Jawa Tengah', 'Cat minyak pada kanvas', '120 × 95 cm', 'RUANG 01 — LUKISAN SEJARAH', 'Lukisan langka dari fase kepulangan Raden Saleh ke tanah air. Menampilkan pasangan mempelai bangsawan dengan kelengkapan busana basahan keraton, kain dodot prada emas, dan tata rias paes ageng yang digarap dengan presisi etnografis tinggi.', 'assets/images/koleksi/pengantin-jawa.jpg', '2026-11-03 10:00:00'),
(7, 'NG-1849-007', 'Hutan Terbakar (Bosbrand)', 'lukisan', 'Raden Saleh (c. 1811–1880)', 1849, 'Jawa Tengah', 'Cat minyak pada kanvas', '300 × 396 cm', 'RUANG 01 — LUKISAN SEJARAH', 'Hadiah Raden Saleh kepada Raja Willem III dari Belanda. Menggambarkan kekacauan kawanan harimau, banteng, dan kijang yang terpojok di tebing curam di tengah kobaran api rimba raya tropis, memancarkan drama kepanikan eksistensial.', 'assets/images/koleksi/hutan-terbakar-raden-saleh.jpg', '2026-11-03 10:00:00'),
(8, 'NG-1947-008', 'Kawan-kawan Revolusi', 'lukisan', 'S. Sudjojono (1913–1986)', 1947, 'Yogyakarta', 'Cat minyak pada karung goni dan kanvas', '95 × 149 cm', 'RUANG 04 — MODERN NUSANTARA', 'Tonggak aliran realisme revolusioner karya \'Bapak Seni Lukis Modern Indonesia\'. Diselesaikan dalam tempo satu hari atas dorongan Bung Karno, menangkap sorot mata jujur, letih, namun penuh tekad baja para pemuda laskar pejuang kemerdekaan 1945.', 'assets/images/koleksi/kawan-kawan-revolusi.jpg', '2026-11-03 10:00:00'),
(9, 'NG-1939-009', 'Di Depan Kelambu Terbuka', 'lukisan', 'S. Sudjojono (1913–1986)', 1939, 'Batavia (Jakarta)', 'Cat minyak pada kanvas', '86 × 66 cm', 'RUANG 04 — MODERN NUSANTARA', 'Karya penting periode Persagi (Persatuan Ahli Gambar Indonesia) yang menolak estetika pemandangan molek Mooi Indie. Sudjojono menampilkan kenyataan hidup rakyat jelata secara telanjang, intim, dan bersahaja dengan kejujuran jiwa (jiwa ketok).', 'assets/images/koleksi/di-depan-kelambu-terbuka.jpg', '2026-11-03 10:00:00'),
(10, 'NG-1953-010', 'Potret Diri Mengisap Pipa', 'lukisan', 'Affandi (1907–1990)', 1953, 'Cirebon / Yogyakarta', 'Cat minyak pada kanvas (teknik plotot langsung dari tube)', '98 × 79 cm', 'RUANG 04 — MODERN NUSANTARA', 'Pencapaian orisinal sang maestro ekspresionisme dunia. Dilukis tanpa kuas, melainkan dengan memencet cat minyak langsung dari tube ke atas kanvas dan menyapukannya memakai telapak tangan serta jemari, memancarkan getaran emosi spontan yang murni.', 'assets/images/koleksi/potret-diri-affandi.jpg', '2026-11-03 10:00:00'),
(11, 'NG-1950-011', 'Perahu-Perahu di Pantai Kusamba', 'lukisan', 'Affandi (1907–1990)', 1950, 'Bali / Yogyakarta', 'Cat minyak pada kanvas', '100 × 130 cm', 'RUANG 04 — MODERN NUSANTARA', 'Deretan jukung bercadik di pesisir Kusamba, Klungkung, Bali. Goresan cat berliuk-liuk membentuk simbol matahari khas Affandi dan ritme gelombang laut yang menghidupkan perjuangan kaum nelayan tradisional.', 'assets/images/koleksi/perahu-madura-affandi.jpg', '2026-11-03 10:00:00'),
(12, 'NG-1930-012', 'Pemandangan Gunung Priangan', 'lukisan', 'Abdullah Suriosubroto (1878–1941)', 1930, 'Bandung, Jawa Barat', 'Cat minyak pada kanvas', '60 × 90 cm', 'RUANG 01 — LUKISAN SEJARAH', 'Contoh mahakarya genre Mooi Indie (Hindia Molek) oleh pelukis pribumi pertama yang mengenyam pendidikan akademis di Belanda. Menampilkan keindahan alam Priangan yang permai dengan gradasi kabut pegunungan dan panorama sawah bertingkat.', 'assets/images/koleksi/pemandangan-mooi-indie.jpg', '2026-11-03 10:00:00'),
(13, 'NG-1938-013', 'Pasar Tradisional di Sanur Bali', 'lukisan', 'Adrien-Jean Le Mayeur de Merpres (1880–1958)', 1938, 'Sanur, Denpasar, Bali', 'Cat minyak pada kanvas', '75 × 90 cm', 'RUANG 04 — MODERN NUSANTARA', 'Karya impresionisme memukau dari pelukis asal Belgia yang jatuh cinta pada kebudayaan Bali dan memperistri penari legong Ni Pollok. Efek cahaya matahari tropis yang menerobos sela dedaunan kamboja menghasilkan pendar warna-warni yang mempesona.', 'assets/images/koleksi/pasar-bali-le-mayeur.jpg', '2026-11-03 10:00:00'),
(14, 'NG-1937-014', 'Penari Legong Bali', 'lukisan', 'Rudolf Bonnet (1895–1978)', 1937, 'Ubud, Gianyar, Bali', 'Pastel dan kapur pada kertas', '65 × 50 cm', 'RUANG 04 — MODERN NUSANTARA', 'Karya figuratif tokoh pendiri perkumpulan seniman Pita Maha di Ubud bersama Cokorda Gde Agung Sukawati dan Walter Spies. Gambar pastel ini merekam keelokan gestur penari Legong dengan pemahaman mendalam atas proporsi anatomi dan keanggunan busana adat Bali.', 'assets/images/koleksi/tari-legong-bonnet.jpg', '2026-11-03 10:00:00'),
(15, 'NG-1920-015', 'Lukisan Wayang Kamasan Epos Ramayana', 'lukisan', 'Sanggar Kamasan Klungkung (tradisi turun-temurun)', 1920, 'Kamasan, Klungkung, Bali', 'Pigmen mineral alami dan jelaga pada kain tenun kapas (ulap)', '115 × 185 cm', 'RUANG 01 — LUKISAN SEJARAH', 'Gaya lukisan naratif dua dimensi khas istana Gelgel dan Klungkung. Dibuat dengan bahan alami murni seperti bubuk tanduk rusa untuk warna putih, jelaga lampu untuk hitam, dan batu oker untuk kuning, menggambarkan lakon kepahlawanan wiracarita Ramayana.', 'assets/images/koleksi/kamasan-ramayana.jpg', '2026-11-03 10:00:00'),
(16, 'NG-1820-016', 'Babad Diponegoro', 'naskah', 'Pangeran Diponegoro (1785–1855)', 1820, 'Yogyakarta / Manado', 'Tinta hitam pada kertas daluang dan kertas Eropa', '30 × 20 cm (400+ halaman)', 'RUANG 02 — MANUSKRIP & ARSIP LITERASI', 'Autobiografi puitis dalam bentuk tembang macapat yang ditulis sendiri oleh Pangeran Diponegoro dalam masa pengasingannya di Manado. Manuskrip ini diakui UNESCO sebagai Warisan Ingatan Dunia (Memory of the World) pada 2013 karena kejujuran sejarah dan nilai luhur budayanya.', 'assets/images/koleksi/babad-diponegoro.jpg', '2026-11-03 10:00:00'),
(17, 'NG-1350-017', 'Sureq Galigo (I La Galigo)', 'naskah', 'Para Pujangga / To Pabicara Bugis Kuno', 1350, 'Luwu, Sulawesi Selatan', 'Tinta alami pada kertas Eropa dan daun lontar beraksara Bugis Kuno', '32 × 21 cm (koleksi ribuan halaman)', 'RUANG 02 — MANUSKRIP & ARSIP LITERASI', 'Epos sastra terpanjang di dunia, melampaui Mahabharata dan Odyssey. Terdiri dari sekitar 300.000 baris syair yang menceritakan kosmologi penciptaan bumi Bugis, petualangan Sawerigading, dan putranya I La Galigo dengan keindahan bahasa arkais tinggi.', 'assets/images/koleksi/la-galigo.jpg', '2026-11-03 10:00:00'),
(18, 'NG-1365-018', 'Kakawin Nagarakretagama (Desawarnana)', 'naskah', 'Mpu Prapanca', 1365, 'Trowulan, Majapahit (ditemukan di Cakranegara, Lombok)', 'Goresan pisau pangot pada lempiran daun lontar beraksara Jawa Kuno', '3,5 × 40 cm (lempir lontar bertali)', 'RUANG 02 — MANUSKRIP & ARSIP LITERASI', 'Naskah pujasastra era keemasan Majapahit di bawah Prabu Hayam Wuruk dan Mahapatih Gajah Mada. Menguraikan tata negara, perdesaan, hukum, dan cakupan wilayah geopolitik Nusantara abad ke-14 yang menjadi inspirasi kebangsaan modern Indonesia.', 'assets/images/koleksi/nagarakretagama.jpg', '2026-11-03 10:00:00'),
(19, 'NG-1380-019', 'Kakawin Sutasoma', 'naskah', 'Mpu Tantular', 1380, 'Majapahit, Jawa Timur', 'Torehan pada daun lontar dengan pewarna jelaga minyak kemiri', '4 × 42 cm', 'RUANG 02 — MANUSKRIP & ARSIP LITERASI', 'Karya sastra filosofis agung tempat tertulisnya pupuh termasyhur 139 bait 5: \'Bhinneka Tunggal Ika tan hana dharma mangrwa\' (Berbeda-beda itu satu, tak ada kebenaran yang mendua), yang kini diabadikan sebagai semboyan resmi persatuan Negara Kesatuan Republik Indonesia.', 'assets/images/koleksi/sutasoma.jpg', '2026-11-03 10:00:00'),
(20, 'NG-1811-020', 'Surat Emas Sultan Syarif Abdurrahman Pontianak', 'naskah', 'Sekretariat Kesultanan Pontianak', 1811, 'Pontianak, Kalimantan Barat', 'Tinta emas dan jelaga pada kertas beriluminasi cat air khas Melayu', '48 × 35 cm', 'RUANG 02 — MANUSKRIP & ARSIP LITERASI', 'Warkah kerajaan beriluminasi emas penuh (surat emas) yang dikirim oleh penguasa Kesultanan Pontianak. Menjadi bukti puncak diplomasi maritim Nusantara dan kecakapan seni kaligrafi Arab Melayu (Jawi) bersanding ragam hias floristik keemasan.', 'assets/images/koleksi/surat-emas-pontianak.jpg', '2026-11-03 10:00:00'),
(21, 'NG-1758-021', 'Manuskrip Hikayat Hang Tuah', 'naskah', 'Katib Istana Melayu Riau-Lingga', 1758, 'Riau / Kepulauan Riau', 'Tinta cina pada kertas bergaris air Eropa (watermarked)', '24 × 18 cm', 'RUANG 02 — MANUSKRIP & ARSIP LITERASI', 'Roman wiracarita epik bahari Melayu yang mengisahkan kesetiaan, persahabatan, dan pertarungan legendaris antara Laksamana Hang Tuah dan Hang Jebat. Memuat falsafah terkenal Melayu: \'Takkan Melayu hilang di bumi\'.', 'assets/images/koleksi/hikayat-hang-tuah.jpg', '2026-11-03 10:00:00'),
(22, 'NG-1814-022', 'Serat Centhini (Suluk Tembangraras)', 'naskah', 'K.G.P.A.A. Amangkunagara III (Sunan Pakubuwana V)', 1814, 'Keraton Surakarta Hadiningrat, Jawa Tengah', 'Tinta pada kertas daluang Jawa beraksara carakan Jawa', '33 × 21 cm (12 jilid ensiklopedis)', 'RUANG 02 — MANUSKRIP & ARSIP LITERASI', 'Ensiklopedia kebudayaan dan spiritualitas Jawa terlengkap yang menghimpun pengetahuan geografi, mistik, musik gamelan, tarian, kuliner, flora fauna, obat-obatan tradisional, hingga arsitektur rumah adat sepanjang pulau Jawa.', 'assets/images/koleksi/serat-centhini.jpg', '2026-11-03 10:00:00'),
(23, 'NG-1780-023', 'Pustaha Lak-Lak Batak Toba', 'naskah', 'Datu (Cendekiawan & Tabib Spiritual Batak)', 1780, 'Tapanuli, Danau Toba, Sumatra Utara', 'Kulit kayu alim (Aquilaria microcarpa) dilipat harmonika dengan tinta jelaga hitam dan merah', '18 × 12 cm (panjang bentang hingga 3 meter)', 'RUANG 02 — MANUSKRIP & ARSIP LITERASI', 'Kitab lipat kulit kayu alim yang memuat ilmu pengobatan herbal (poda pardomuan), astrologi agraris (porhalaan), dan penangkal bala spiritual. Diapit dua bilah papan kayu berukir motif reptil suci Ilik (cicak penjaga kearifan).', 'assets/images/koleksi/pustaha-laklak.jpg', '2026-11-03 10:00:00'),
(24, 'NG-1518-024', 'Sanghyang Siksa Kandang Karesian', 'naskah', 'Resi Kerajaan Sunda Pajajaran', 1518, 'Tatar Pasundan, Jawa Barat', 'Daun gebang (Corypha utan) beraksara Sunda Kuno', '3,2 × 34 cm', 'RUANG 02 — MANUSKRIP & ARSIP LITERASI', 'Kitab pedoman moral dan ensiklopedia peradaban Sunda kuno zaman Sri Baduga Maharaja (Prabu Siliwangi). Menguraikan profesi masyarakat, etika kepemimpinan, keprajuritan, hingga doktrin \'Dasa Prebakti\' (sepuluh kesetiaan sosial).', 'assets/images/koleksi/sanghyang-siksakandang.jpg', '2026-11-03 10:00:00'),
(25, 'NG-1790-025', 'Mushaf Al-Qur\'an Iluminasi Emas Kesultanan Aceh', 'naskah', 'Katib Kesultanan Aceh Darussalam', 1790, 'Banda Aceh, Nanggroe Aceh Darussalam', 'Tinta emas murni, vermilion, dan nila pada kertas Eropa bertanda air singa VOC', '36 × 24 cm', 'RUANG 02 — MANUSKRIP & ARSIP LITERASI', 'Karya kaligrafi Islam terunggul di Asia Tenggara. Ciri khas iluminasi Aceh memadukan ornamen gerbang mahligai bersayap tiga (tripartite vault) berlapis emas pekat, vermilion terang, dan biru kobalt yang anggun.', 'assets/images/koleksi/al-quran-iluminasi-aceh.jpg', '2026-11-03 10:00:00'),
(26, 'NG-1725-026', 'Babad Tanah Jawi', 'naskah', 'Carik Bajra / Para Pujangga Kartasura', 1725, 'Kartasura / Surakarta, Jawa Tengah', 'Tinta hitam pada kertas daluang alami', '31 × 20 cm', 'RUANG 02 — MANUSKRIP & ARSIP LITERASI', 'Karya historiografi tradisional Jawa yang merunut silsilah para raja dari nabi Adam, para dewa pewayangan, Dinasti Mataram Kuno, Majapahit, Demak, Pajang, hingga era Kesultanan Mataram Islam, memadukan mitos legitimasi dan peristiwa nyata.', 'assets/images/koleksi/babad-tanah-jawi.jpg', '2026-11-03 10:00:00'),
(27, 'NG-1890-027', 'Hikayat Prang Sabi', 'naskah', 'Tgk Chik Pante Kulu', 1890, 'Aceh Besar / Pidie, Aceh', 'Tinta pada kertas lokal dan Eropa beraksara Jawoe (Jawi Aceh)', '22 × 16 cm', 'RUANG 02 — MANUSKRIP & ARSIP LITERASI', 'Karya sastra heroik bernuansa spiritual yang dibacakan para pejuang Aceh untuk mengobarkan semangat membela kedaulatan tanah air melawan agresi Belanda. Memiliki pengaruh psikologis dan historis sangat mendalam dalam Perang Aceh (1873–1904).', 'assets/images/koleksi/hikayat-prang-sabi.jpg', '2026-11-03 10:00:00'),
(28, 'NG-1250-028', 'Arca Prajnaparamita dari Candi Singhasari', 'artefak', 'Pemahat Utama Kerajaan Singhasari', 1250, 'Singhasari, Malang, Jawa Timur', 'Batu andesit dipahat halus', 'Tinggi 126 cm, lebar 56 cm', 'RUANG 03 — ARTEFAK & LITOGRAFI KERAJAAN', 'Mahakarya seni pahat klasik tertinggi Nusantara yang menggambarkan Dewi Kebijaksanaan Sempurna dalam tradisi Buddha Vajrayana. Diyakini sebagai arca perwujudan (dewapatima) Ken Dedes, ibu suri yang melahirkan wangsa Rajasa raja-raja Singhasari dan Majapahit.', 'assets/images/koleksi/arca-prajnaparamita.jpg', '2026-11-03 10:00:00'),
(29, 'NG-1600-029', 'Keris Kiai Naga Siluman Pangeran Diponegoro', 'artefak', 'Mpu Keris Pilihan Mataram Islam', 1600, 'Yogyakarta', 'Besi tempa, meteorit pamor perak, tatahan emas murni, dan kayu timaha', 'Panjang bilah 36 cm, panjang total dengan warangka 51 cm', 'RUANG 03 — ARTEFAK & LITOGRAFI KERAJAAN', 'Pusaka legendaris ageman pribadi Pangeran Diponegoro selama Perang Jawa. Bilahnya berlekuk dengan gandik berbentuk kepala naga bermahkota emas murni yang badannya menyusuri bilah hingga pucuk, baru direpatriasi ke tanah air pada tahun 2020.', 'assets/images/koleksi/keris-kiai-naga-siluman.jpg', '2026-11-03 10:00:00'),
(30, 'NG-0850-030', 'Arca Siwa Mahadewa Candi Prambanan', 'artefak', 'Silpin Kerajaan Medang (Mataram Kuno era Rakai Pikatan)', 856, 'Prambanan, Sleman, DI Yogyakarta', 'Batu andesit monolitik', 'Tinggi 300 cm (3 meter)', 'RUANG 03 — ARTEFAK & LITOGRAFI KERAJAAN', 'Arca terpenting dalam bilik utama Candi Prambanan (Loro Jonggrang). Memiliki empat lengan yang memegang aksamala (tasbih), camara (penghalau lalat), trisula, dan berhias tengkorak ardhacandra di mahkotanya, sebagai manifestasi Dewa Penguasa Semesta.', 'assets/images/koleksi/arca-siwa-mahadewa.jpg', '2026-11-03 10:00:00'),
(31, 'NG-0400-031', 'Prasasti Yupa Muara Kaman Kutai', 'artefak', 'Brahmana Kerajaan Kutai Martapura', 400, 'Muara Kaman, Kutai Kartanegara, Kalimantan Timur', 'Batu andesit tiang monolit bertatah aksara Pallawa awal', 'Tinggi ± 180 cm', 'RUANG 03 — ARTEFAK & LITOGRAFI KERAJAAN', 'Bukti tertulis tertua dalam sejarah peradaban Nusantara yang menandai berakhirnya masa praaksara. Mengisahkan kedermawanan Maharaja Mulawarman yang menyedekahkan 20.000 ekor sapi kepada para brahmana di tanah suci Waprakeswara.', 'assets/images/koleksi/prasasti-yupa-kutai.jpg', '2026-11-03 10:00:00'),
(32, 'NG-0450-032', 'Prasasti Ciaruteun Tarumanagara', 'artefak', 'Pemahat Titah Raja Purnawarman', 450, 'Ciampea, Bogor, Jawa Barat', 'Batu kali alami (batu sungai) bertatah aksara Pallawa dan telapak kaki', 'Panjang 200 cm, tinggi 150 cm, bobot 8 ton', 'RUANG 03 — ARTEFAK & LITOGRAFI KERAJAAN', 'Memuat pahatan sepasang telapak kaki Raja Purnawarman yang diibaratkan seperti kaki Dewa Wisnu, melambangkan kekuasaan, keperkasaan, dan perlindungan raja atas rakyat kerajaan maritim Tarumanagara di barat pulau Jawa.', 'assets/images/koleksi/prasasti-ciaruteun.jpg', '2026-11-03 10:00:00'),
(33, 'NG-0300-033', 'Nekara Perunggu Bulan Pejeng Bali', 'artefak', 'Pande Perunggu Tradisi Dong Son / Bali Kuno', 300, 'Pejeng, Tampaksiring, Gianyar, Bali', 'Coran perunggu monolitik masif dengan teknik cire-perdue', 'Tinggi 186 cm, diameter bidang pukul 160 cm (nekara terbesar di dunia)', 'RUANG 03 — ARTEFAK & LITOGRAFI KERAJAAN', 'Nekara perunggu utuh terbesar di dunia dari zaman perundagian. Dikenal masyarakat Bali sebagai \'Bulan Jatuh Pejeng\' yang disakralkan di paviliun panggung tinggi pura, berhias ragam hias topeng antropomorfik dengan mata melotot dan anting bulat.', 'assets/images/koleksi/nekara-pejeng.jpg', '2026-11-03 10:00:00'),
(34, 'NG-1350-034', 'Topeng Emas Pemakaman Bangsawan Majapahit', 'artefak', 'Kemasan (Pengrajin Emas Istana) Majapahit', 1350, 'Trowulan / Tuban, Jawa Timur', 'Lembaran emas murni 22 karat teknik ketok repoussé', '18 × 15 cm, berat 125 gram', 'RUANG 03 — ARTEFAK & LITOGRAFI KERAJAAN', 'Topeng upacara pemakaman ningrat Majapahit yang diletakkan menutupi wajah jenazah bangsawan untuk membimbing arwah menuju alam keabadian. Garis pahatan bibir menyunggingkan senyum lembut nirwana yang damai.', 'assets/images/koleksi/topeng-emas-majapahit.jpg', '2026-11-03 10:00:00'),
(35, 'NG-1889-035', 'Mahkota Emas Bertakhta Berlian Kesultanan Siak', 'artefak', 'Empu Kriya Emas Diraja Siak', 1889, 'Siak Sri Indrapura, Riau', 'Emas murni, bertakhtakan berlian intan dan batu rubi delima', 'Diameter 33 cm, tinggi 27 cm, berat 1,8 kg', 'RUANG 03 — ARTEFAK & LITOGRAFI KERAJAAN', 'Mahkota regalia kedaulatan Sultan Siak Sri Indrapura. Pada tahun 1945, Sultan Syarif Kasim II secara sukarela menyerahkan mahkota ini beserta dana 13 juta gulden kepada Presiden Soekarno demi menopang perjuangan republik baru Indonesia.', 'assets/images/koleksi/mahkota-sultan-siak.jpg', '2026-11-03 10:00:00'),
(36, 'NG-1700-036', 'Pedang Jenawi Diraja Melayu', 'artefak', 'Pandai Besi Kesultanan Riau-Lingga', 1700, 'Kepulauan Riau', 'Baja damaskus pamor, gagang perak berukir sulur, dan sarung kayu cendana bersalut emas', 'Panjang bilah 100 cm, panjang total 120 cm', 'RUANG 03 — ARTEFAK & LITOGRAFI KERAJAAN', 'Senjata pusaka kebesaran para panglima perang Melayu. Berbilah baja panjang bermata dua yang ditempa lurus dengan kelentingan tinggi, melambangkan ketegasan sikap dan kepatuhan pada hukum kedaulatan daulat sultan.', 'assets/images/koleksi/pedang-jenawi-riau.jpg', '2026-11-03 10:00:00'),
(37, 'NG-1875-037', 'Patung Leluhur Korwar Biak Papua', 'artefak', 'Pemahat Adat Suku Biak Numfor', 1875, 'Teluk Cenderawasih, Biak, Papua', 'Kayu keras besi pulau dipahat dengan manik-manik kaca biru pada kelopak mata', 'Tinggi 32 cm, lebar 16 cm', 'RUANG 03 — ARTEFAK & LITOGRAFI KERAJAAN', 'Patung media penghubung spiritual antara orang hidup dan roh nenek moyang suku maritim Biak. Memiliki proporsi kepala besar dengan hidung menyerupai paruh burung dan tangan memegang perisai motif ukiran flora reptil laut.', 'assets/images/koleksi/patung-korwar-papua.jpg', '2026-11-03 10:00:00'),
(38, 'NG-1750-038', 'Patung Penjaga Hampatong Dayak Ngaju', 'artefak', 'Tukang Ukir Adat Dayak Ngaju', 1750, 'Sungai Kahayan, Kalimantan Tengah', 'Kayu ulin (kayu besi Kalimantan / Eusideroxylon zwageri)', 'Tinggi 210 cm', 'RUANG 03 — ARTEFAK & LITOGRAFI KERAJAAN', 'Patung penolak bala dan pelindung desa yang ditancapkan di muara sungai atau halaman rumah Betang. Dibuat dari kayu ulin kokoh yang tahan ratusan tahun terhadap terpaan iklim hujan tropis, mencerminkan ketabahan manusia pedalaman Borneo.', 'assets/images/koleksi/patung-hampatong-dayak.jpg', '2026-11-03 10:00:00'),
(39, 'NG-0400-039', 'Arca Buddha Dipangkara Sikendeng Sulawesi', 'artefak', 'Pande Perunggu Tradisi Seni Amarawati', 400, 'Sikendeng, Sungai Sampaga, Mamuju, Sulawesi Barat', 'Coran perunggu padat dengan gaya Amarawati India Selatan', 'Tinggi 58 cm, berat 9,5 kg', 'RUANG 03 — ARTEFAK & LITOGRAFI KERAJAAN', 'Artefak Buddha tertua di Nusantara. Menggambarkan Buddha Dipangkara sang pelindung para pelaut maritim samudra. Memperlihatkan lipatan jubah tembus pandang yang elegan khas gaya seni patung Amarawati, membuktikan jalur perdagangan kuno melewati selat Makassar.', 'assets/images/koleksi/arca-buddha-sikendeng.jpg', '2026-11-03 10:00:00'),
(40, 'NG-0900-040', 'Genta Upacara Perunggu Pendeta Jawa Kuno', 'artefak', 'Pandai Logam Suci Medang Mataram Kuno', 900, 'Kedu / Prambanan, Jawa Tengah', 'Perunggu bertatahkan ukiran sulur tumpal dan tangkai puncak vajra berujung tiga', 'Tinggi 24 cm, diameter 14 cm', 'RUANG 03 — ARTEFAK & LITOGRAFI KERAJAAN', 'Peralatan liturgis sakral (ghanta) yang dibunyikan oleh pendeta resi saat melantunkan mantra doa puja dalam upacara keagamaan Hindu-Buddha Jawa kuno. Bunyinya dipercaya menyucikan ruangan dan mengundang kehadiran para dewata.', 'assets/images/koleksi/genta-perunggu-candi.jpg', '2026-11-03 10:00:00'),
(41, 'NG-1370-041', 'Arca Perwujudan Ratu Tribhuwana Tunggadewi', 'artefak', 'Silpin Istana Kerajaan Majapahit', 1370, 'Candi Rimbi, Jombang, Jawa Timur', 'Batu andesit dipahat detail ragam hias praba perhiasan kerajaan', 'Tinggi 205 cm, lebar dasar 70 cm', 'RUANG 03 — ARTEFAK & LITOGRAFI KERAJAAN', 'Arca pemuliaan ratu penguasa ketiga Majapahit, ibunda dari Hayam Wuruk. Dipersonifikasikan sebagai Parwati dengan pakaian kebesaran istana bertabur motif bunga ceplok, mencerminkan kepemimpinan perempuan perkasa dalam sejarah Nusantara.', 'assets/images/koleksi/arca-tribhuwana-majapahit.jpg', '2026-11-03 10:00:00'),
(42, 'NG-1860-042', 'Kain Batik Parang Rusak Barong Surakarta', 'wastra', 'Abdi Dalem Pembatik Putri Keraton Surakarta', 1860, 'Surakarta, Jawa Tengah', 'Malam lilin lebah, pewarna alami soga jambal dan nila pada kain katun primissima mori', '250 × 105 cm', 'RUANG 03 — ARTEFAK & LITOGRAFI KERAJAAN', 'Motif batik larangan (awisan dalem) bernilai sakral tertinggi yang dahulu hanya boleh dikenakan oleh Raja/Sultan. Garis diagonal lidah parang berukuran lebih dari 8 cm melambangkan ombak laut selatan yang tak henti membentur tebing, simbol kegigihan mengendalikan hawa nafsu.', 'assets/images/koleksi/batik-parang-rusak-barong.jpg', '2026-11-03 10:00:00'),
(43, 'NG-1870-043', 'Kain Songket Lepus Berlapis Benang Emas Palembang', 'wastra', 'Pengrajin Tenun Tradisional Palembang', 1870, 'Palembang, Sumatra Selatan', 'Sutra murni tenun pakan tambahan dengan benang emas jantung murni', '210 × 90 cm', 'RUANG 03 — ARTEFAK & LITOGRAFI KERAJAAN', 'Dikenal sebagai \'Ratu Segala Kain Nusantara\' (Queen of Fabrics). Lepus berarti merata; hampir seluruh permukaan kain sutra merah tua tertutup rapat oleh kilauan tenunan benang emas murni peninggalan kemewahan tradisi kemaharajaan Sriwijaya.', 'assets/images/koleksi/songket-palembang-lepus.jpg', '2026-11-03 10:00:00'),
(44, 'NG-1890-044', 'Tenun Ikat Hinggi Pasola Sumba Timur', 'wastra', 'Penun Wanita Adat Marapu Sumba', 1890, 'Kambera, Sumba Timur, Nusa Tenggara Timur', 'Kapas pintal tangan, pewarna akar mengkudu (merah) dan tarum nila (biru tua)', '260 × 120 cm', 'RUANG 03 — ARTEFAK & LITOGRAFI KERAJAAN', 'Kain selimut kebesaran kaum bangsawan (maramba) Sumba. Memuat ragam motif simbolik sakral seperti kuda ksatria pasola, buaya penjaga alam gaib, udang simbol kelahiran kembali, dan andung (pohon tengkorak) lambang kejayaan perang masa lampau.', 'assets/images/koleksi/kain-tenun-ikat-sumba.jpg', '2026-11-03 10:00:00'),
(45, 'NG-1880-045', 'Kain Gringsing Dobel Ikat Wayang Puter Tenganan Bali', 'wastra', 'Penun Tradisi Adat Bali Aga Tenganan Pagringsingan', 1880, 'Tenganan Pagringsingan, Karangasem, Bali', 'Kapas lokal, teknik dobel ikat (tenun ganda pakan & lusi), pewarna alami buah babakan tingi dan kepundung', '200 × 50 cm', 'RUANG 03 — ARTEFAK & LITOGRAFI KERAJAAN', 'Satu-satunya kain tenun teknik dobel ikat (double ikat) di seluruh Asia Tenggara yang membutuhkan waktu pembuatan hingga bertahun-tahun. \'Gring\' berarti sakit dan \'sing\' berarti tidak, diyakini masyarakat Bali Aga memiliki kekuatan magis penolak wabah penyakit dan marabahaya.', 'assets/images/koleksi/kain-gringsing-wayang.jpg', '2026-11-03 10:00:00'),
(46, 'NG-1943-046', 'Batik Tulis Pesisir Pekalongan Djawa Hokokai', 'wastra', 'Pengrajin Peranakan Tionghoa Pekalongan', 1943, 'Pekalongan, Jawa Tengah', 'Malam canting halus, pewarna kimia pekat pada kain katun sutra', '240 × 105 cm', 'RUANG 03 — ARTEFAK & LITOGRAFI KERAJAAN', 'Lahir pada masa pendudukan Jepang (1942–1945). Memiliki pola \'Pagi-Sore\' dengan dua komposisi berbeda dalam sehelai kain, dihiasi motif bunga sakura, bunga krisan, dan kupu-kupu yang sangat padat dan mendetail (isen-isen cecek sawut rumit).', 'assets/images/koleksi/batik-pesisiran-hokokai.jpg', '2026-11-03 10:00:00'),
(47, 'NG-1885-047', 'Kain Tapis Lampung Kapal Jung Sarat Benang Emas', 'wastra', 'Wanita Penenun Adat Saibatin / Pepadun', 1885, 'Pugung, Lampung Selatan', 'Tenun kapas bergaris warna alami dengan sulaman benang emas teknik cucuk sulam kawat', '125 × 110 cm', 'RUANG 03 — ARTEFAK & LITOGRAFI KERAJAAN', 'Kain sarung upacara adat kaum ningrat wanita Lampung. Motif kapal jung melambangkan wahana perjalanan bahari kehidupan manusia sejak lahir, menempuh gelombang duniawi, hingga berlabuh ke pelabuhan alam baka dengan penuh martabat luhur.', 'assets/images/koleksi/tapis-lampung-kapal.jpg', '2026-11-03 10:00:00'),
(48, 'NG-1895-048', 'Kain Tenun Ulos Ragi Hidup Batak Toba', 'wastra', 'Partonun (Penun Ahli) Batak Toba', 1895, 'Silindung / Balige, Toba, Sumatra Utara', 'Kapas tenun gedongan tradisional, tiga bagian bidang disambung tangan secara cermat', '210 × 120 cm', 'RUANG 03 — ARTEFAK & LITOGRAFI KERAJAAN', 'Kasta tertinggi dalam hierarki wastra tenun adat Batak. \'Ragi Hidup\' melambangkan kesinambungan garis keturunan dan nafas kehidupan, diserahkan oleh orang tua pengantin wanita kepada ibu pengantin pria sebagai ikatan sakral kekeluargaan dalihan na tolu.', 'assets/images/koleksi/ulos-ragidup-batak.jpg', '2026-11-03 10:00:00'),
(49, 'NG-1880-049', 'Kain Tenun Sekomandi / Rongkong Toraja Sa\'dan', 'wastra', 'Penenun Wanita Adat Rongkong Toraja', 1880, 'Rongkong / Tana Toraja, Sulawesi Selatan', 'Tenun ikat benang kapas pintal alami dengan pewarna akar kayu cabak (merah bata) dan lumpur mineral', '220 × 140 cm', 'RUANG 03 — ARTEFAK & LITOGRAFI KERAJAAN', 'Salah satu tenun tertua di pulau Sulawesi. Menampilkan motif \'Ulu Karua\' dan stilasi \'Pa\'tedong\' (tanduk kerbau pusaka) dengan komposisi warna bumi (terakota, hitam jelaga, dan krem kapas), digunakan dalam ritual kematian agung Rambu Solo.', 'assets/images/koleksi/tenun-toraja-sekomandi.jpg', '2026-11-03 10:00:00'),
(50, 'NG-1875-050', 'Tatahan Sungging Wayang Kulit Raden Werkudara', 'wastra', 'Pengrajin Tatah Sungging Keraton Kasultanan Yogyakarta', 1875, 'Kasultanan Ngayogyakarta Hadiningrat, Jawa Tengah', 'Kulit kerbau pilihan (walulang), cat pigmen mineral alami dengan prada emas murni 24 karat, dan gapit tanduk kerbau bule', 'Tinggi figur 75 cm, tinggi total dengan gapit 105 cm', 'RUANG 03 — ARTEFAK & LITOGRAFI KERAJAAN', 'Karya adi luhung seni tatah sungging pewayangan Jawa. Menggambarkan ksatria perkasa Pandawa kedua, Werkudara (Bima), dengan busana kain kotak-kotak hitam-putih (kampuh poleng rekathawarna), gelung pudak sinumpet, serta senjata kuku Pancanaka penegak keadilan.', 'assets/images/koleksi/wayang-kulit-purwa-bima.jpg', '2026-11-03 10:00:00');
